class Rule:
    def __eq__(self, other):
        return isinstance(other, self.__class__)

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}()"

    def __hash__(self):
        return id(self)

    @property
    def __dict__(self):
        return {
            "type": self.__class__.__name__,
        }


