        nodes: list[list[GraphNode]] = [
            list(root_node.values()) for root_node in self.__roots__.values()
        ]
        if pointers is None:
            pointers = Pointers()
        graph_view: list[str] = []
        for root_node in nodes:
            for node in root_node:
                graph_view.extend(
                    [
                        node.print(
